presets.css:
/* =========================================================
   Puff · 雾蓝 × iOS 超淡玻璃
   ========================================================= */

.off-app {
  --off-list-bg:
    linear-gradient(
      145deg,
      rgba(246, 251, 255, 0.96),
      rgba(250, 252, 253, 0.91)
    );

  --off-list-border: rgba(255, 255, 255, 0.90);
  --off-list-radius: 22px;
  --off-list-ava-size: 52px;

  --off-blue: #b0d1e8;
  --off-blue-light: #e3f0f8;
  --off-blue-soft: rgba(185, 216, 235, 0.20);

  --off-glass: rgba(255, 255, 255, 0.64);
  --off-glass-heavy: rgba(255, 255, 255, 0.80);

  --off-glass-shadow:
    0 8px 30px rgba(75, 105, 125, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}


/* 筛选 */

.off-inbox-filter {
  background: rgba(255, 255, 255, 0.46);
  border: 1px solid rgba(255, 255, 255, 0.74);
  border-radius: 999px;

  backdrop-filter: blur(20px) saturate(120%);
  -webkit-backdrop-filter: blur(20px) saturate(120%);
}

.off-inbox-filter button {
  color: #929da4;
  background: transparent;
  border-radius: 999px;
}

.off-inbox-filter button.on {
  color: #fff;

  background:
    linear-gradient(
      135deg,
      #c4deee,
      #a9cce4
    );

  box-shadow:
    0 4px 12px rgba(135, 183, 210, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.68);
}


/* 列表 */

.off-list {
  background: var(--off-list-bg);

  border: 1px solid var(--off-list-border);
  border-radius: var(--off-list-radius);

  overflow: hidden;

  backdrop-filter: blur(28px) saturate(120%);
  -webkit-backdrop-filter: blur(28px) saturate(120%);

  box-shadow: var(--off-glass-shadow);
}

.off-list-btn {
  padding: 15px 14px 15px 16px;
}

.off-list-btn:hover {
  background: rgba(190, 220, 237, 0.08);
}

.off-list-ava {
  width: var(--off-list-ava-size);
  height: var(--off-list-ava-size);

  border-radius: 50%;

  border: 2px solid rgba(255, 255, 255, 0.9);

  box-shadow:
    0 3px 12px rgba(80, 110, 130, 0.07),
    0 0 0 3px rgba(205, 228, 241, 0.20);
}

.off-list-body strong {
  font-size: 1.3rem;
  color: #414a50;
  font-weight: 600;
}

.off-list-body span {
  opacity: 0.68;
  color: #849097;
}

.off-list-go.is-new {
  font-size: 20px;
  font-weight: 300;
  color: #9fc5dc;
}


/* =========================================================
   当面共处
   ========================================================= */

.off-app.off-app-session {
  --off-card-user:
    linear-gradient(
      135deg,
      rgba(225, 240, 249, 0.70),
      rgba(246, 251, 254, 0.60)
    );

  --off-card-peer:
    rgba(255, 255, 255, 0.66);

  --off-card-border:
    rgba(255, 255, 255, 0.84);

  --off-card-shadow:
    0 8px 30px rgba(70, 100, 120, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);

  --off-prose-font:
    var(--display),
    "Noto Serif SC",
    "Source Han Serif SC",
    Georgia,
    serif;

  --off-dock-bg:
    rgba(247, 252, 255, 0.72);

  color: var(--ink);
}


/* 无壁纸 */

.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(211, 232, 244, 0.48),
      transparent 35%
    ),
    radial-gradient(
      circle at 85% 80%,
      rgba(230, 242, 249, 0.62),
      transparent 40%
    ),
    #f4f8fa;
}


/* 顶栏 */

.off-app.off-app-session .off-stage-head {
  background:
    rgba(249, 253, 255, 0.60);

  border-bottom:
    1px solid rgba(255, 255, 255, 0.76);

  backdrop-filter:
    blur(26px) saturate(120%);

  -webkit-backdrop-filter:
    blur(26px) saturate(120%);
}

.off-app.off-app-session .off-stage-scene {
  font-weight: 500;
  letter-spacing: 0.04em;
}


/* 消息 */

.off-app.off-app-session .off-passage-sheet {
  background:
    var(--off-card-peer);

  border:
    1px solid var(--off-card-border);

  box-shadow:
    var(--off-card-shadow);

  border-radius:
    20px;

  backdrop-filter:
    blur(24px) saturate(120%);

  -webkit-backdrop-filter:
    blur(24px) saturate(120%);
}

.off-app.off-app-session
.off-passage.is-me
.off-passage-sheet {
  background:
    var(--off-card-user);

  border-color:
    rgba(178, 211, 230, 0.40);
}


/* 推演 */

.off-app .off-thinking-chip {
  background:
    rgba(255, 255, 255, 0.50);

  color:
    #8c9ba3;

  border:
    1px solid rgba(255, 255, 255, 0.72);

  border-radius:
    999px;

  padding:
    3px 11px;

  font-size:
    11px;

  backdrop-filter:
    blur(14px);

  -webkit-backdrop-filter:
    blur(14px);
}


/* 正文 */

.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain,
.off-app.off-app-session .off-prose-dial {
  font-family: var(--off-prose-font);
  line-height: 1.85;
  font-size: 14.5px;
  color: var(--ink);
}

.off-app.off-app-session .off-prose-dial {
  font-weight: 500;
}

.off-app.off-app-session
.off-passage.is-me
.off-prose-dial {
  font-weight: 400;
}


/* Dock */

.off-app.off-app-session .off-stage-dock {
  background:
    var(--off-dock-bg);

  backdrop-filter:
    blur(28px) saturate(125%);

  -webkit-backdrop-filter:
    blur(28px) saturate(125%);

  border-top:
    1px solid rgba(255, 255, 255, 0.78);
}


/* 输入框 */

.off-compose-bar {
  background:
    rgba(255, 255, 255, 0.72);

  border:
    1px solid rgba(255, 255, 255, 0.90);

  border-radius:
    999px;

  backdrop-filter:
    blur(24px) saturate(120%);

  -webkit-backdrop-filter:
    blur(24px) saturate(120%);

  box-shadow:
    0 5px 20px rgba(70, 100, 120, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}


/* 发送 */

.off-compose-send {
  background:
    linear-gradient(
      135deg,
      #c4ddec,
      #a9cbdf
    );

  color: #fff;

  border-radius: 50%;

  box-shadow:
    0 4px 12px rgba(125, 177, 207, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.70);
}


/* 滚动条 */

.off-app ::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

.off-app ::-webkit-scrollbar-thumb {
  background: rgba(155, 195, 217, 0.20);
  border-radius: 999px;
}

.off-app ::-webkit-scrollbar-track {
  background: transparent;
}
